"""Final comprehensive test to verify the CPU validation fix."""

import sys
import os
import mock
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from libcloudforensics.providers.gcp.internal import compute
from libcloudforensics.providers.gcp import forensics
from libcloudforensics.providers.gcp.internal import project
from libcloudforensics import errors


def test_direct_method_validation():
    """Test validation directly in GetOrCreateAnalysisVm method."""
    print("=== Testing direct method validation ===")

    gcp_compute = compute.GoogleCloudCompute("test-project", default_zone="us-central1-f")

    # Test cases: (cpu_count, should_be_valid)
    test_cases = [
        (1, False), (2, True), (3, False), (4, True), (5, False),
        (6, False), (7, False), (8, True), (9, False), (10, False),
        (15, False), (16, True), (20, False), (25, False), (32, True)
    ]

    for cpu_count, should_be_valid in test_cases:
        with mock.patch.object(gcp_compute, 'GetInstance') as mock_get_instance:
            mock_get_instance.side_effect = errors.ResourceNotFoundError('Not found', 'test')

            try:
                gcp_compute.GetOrCreateAnalysisVm(
                    vm_name=f"test-vm-{cpu_count}",
                    boot_disk_size=10,
                    cpu_cores=cpu_count
                )
                # If we get here, validation passed
                if should_be_valid:
                    print(f"  ✓ CPU {cpu_count}: Correctly accepted")
                else:
                    print(f"  ✗ CPU {cpu_count}: Should have been rejected but was accepted")
            except ValueError as e:
                if "Invalid CPU cores" in str(e):
                    if not should_be_valid:
                        print(f"  ✓ CPU {cpu_count}: Correctly rejected")
                    else:
                        print(f"  ✗ CPU {cpu_count}: Should have been accepted but was rejected: {e}")
                else:
                    # Some other ValueError
                    if should_be_valid:
                        print(f"  ✓ CPU {cpu_count}: Passed validation (failed later)")
                    else:
                        print(f"  ? CPU {cpu_count}: Different ValueError: {e}")
            except Exception as e:
                # Other exceptions are expected due to mocking
                if should_be_valid:
                    print(f"  ✓ CPU {cpu_count}: Passed validation (failed later with {type(e).__name__})")
                else:
                    print(f"  ? CPU {cpu_count}: Failed with {type(e).__name__} instead of ValueError")


def test_forensics_module_validation():
    """Test that forensics.StartAnalysisVm also validates CPU counts."""
    print("\n=== Testing forensics module validation ===")

    # Test cases: (cpu_count, should_be_valid)
    test_cases = [(2, True), (3, False), (4, True), (5, False), (8, True)]

    for cpu_count, should_be_valid in test_cases:
        with mock.patch('libcloudforensics.providers.gcp.internal.project.GoogleCloudProject') as mock_project_class:
            # Set up the mock project and compute
            mock_project = mock_project_class.return_value
            mock_compute = mock_project.compute

            with mock.patch.object(mock_compute, 'GetOrCreateAnalysisVm') as mock_get_or_create:

                # Configure the mock to either succeed or fail appropriately
                if should_be_valid:
                    mock_get_or_create.return_value = (mock.MagicMock(), True)
                else:
                    mock_get_or_create.side_effect = ValueError(
                        f'Invalid CPU cores: {cpu_count}. GCP e2-standard machine types '
                        f'only support the following CPU counts: [2, 4, 8, 16, 32]'
                    )

                try:
                    forensics.StartAnalysisVm(
                        project="test-project",
                        vm_name=f"test-vm-{cpu_count}",
                        zone="us-central1-f",
                        boot_disk_size=10,
                        boot_disk_type="pd-standard",
                        cpu_cores=cpu_count
                    )

                    if should_be_valid:
                        print(f"  ✓ CPU {cpu_count}: Forensics module accepted valid CPU count")
                    else:
                        print(f"  ✗ CPU {cpu_count}: Forensics module should have rejected invalid CPU count")

                except ValueError as e:
                    if "Invalid CPU cores" in str(e):
                        if not should_be_valid:
                            print(f"  ✓ CPU {cpu_count}: Forensics module correctly rejected invalid CPU count")
                        else:
                            print(f"  ✗ CPU {cpu_count}: Forensics module incorrectly rejected valid CPU count: {e}")
                    else:
                        print(f"  ? CPU {cpu_count}: Different ValueError in forensics: {e}")
                except Exception as e:
                    print(f"  ? CPU {cpu_count}: Exception in forensics: {type(e).__name__}: {e}")


def test_edge_cases():
    """Test edge cases and boundary conditions."""
    print("\n=== Testing edge cases ===")

    gcp_compute = compute.GoogleCloudCompute("test-project", default_zone="us-central1-f")

    # Test boundary values
    edge_cases = [0, -1, -5, 64, 100]

    for cpu_count in edge_cases:
        with mock.patch.object(gcp_compute, 'GetInstance') as mock_get_instance:
            mock_get_instance.side_effect = errors.ResourceNotFoundError('Not found', 'test')

            try:
                gcp_compute.GetOrCreateAnalysisVm(
                    vm_name=f"test-vm-{cpu_count}",
                    boot_disk_size=10,
                    cpu_cores=cpu_count
                )
                print(f"  ✗ CPU {cpu_count}: Negative/zero/large value was incorrectly accepted")
            except ValueError as e:
                if "Invalid CPU cores" in str(e):
                    print(f"  ✓ CPU {cpu_count}: Correctly rejected")
                else:
                    print(f"  ? CPU {cpu_count}: Different ValueError: {e}")
            except Exception as e:
                print(f"  ✓ CPU {cpu_count}: Rejected with {type(e).__name__}")


if __name__ == '__main__':
